export const CHECKOUT_CLAREZA_1610_ARQUIVOS = Object.keys(BLOCOS)

/** Tira as mudanças KINEO-CHECKOUT-CLAREZA-1610 de `src` (caminho relativo com "/"). Outros arquivos voltam intocados. */
export function semClareza1610(rel, src) {
  const blocos = BLOCOS[String(rel).replace(/\\/g, '/')]
  if (!blocos || typeof src !== 'string') return src
  const crlf = src.includes('\r\n')
  let s = src.replace(/\r\n/g, '\n')
  if (!s.includes(MARCA_CHECKOUT_CLAREZA_1610)) return src
  for (const [antes, depois] of blocos) {
    const n = s.split(depois).length - 1
    if (n !== 1) throw new Error(`desfaz ${MARCA_CHECKOUT_CLAREZA_1610}: ${rel}: bloco achado ${n}× — ${depois.slice(0, 60)}`)
    s = s.split(depois).join(antes)
  }
  if (s.includes(MARCA_CHECKOUT_CLAREZA_1610)) throw new Error(`desfaz ${MARCA_CHECKOUT_CLAREZA_1610}: ${rel}: sobrou linha marcada`)
  return crlf ? s.replace(/\n/g, '\r\n') : s
}
